import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.C8xYrcAN.js";const h=JSON.parse('{"title":"Contact Us","description":"Contact Chaldea for support, privacy complaints, personal information rights requests, feedback and community discussions.","frontmatter":{"title":"Contact Us","description":"Contact Chaldea for support, privacy complaints, personal information rights requests, feedback and community discussions."},"headers":[],"relativePath":"guide/contact.md","filePath":"guide/contact.md","lastUpdated":1792948524000}'),o={name:"guide/contact.md"};function r(n,e,c,l,u,d){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="contact-us" tabindex="-1">Contact Us <a class="header-anchor" href="#contact-us" aria-label="Permalink to &quot;Contact Us&quot;">​</a></h1><p>Contact us if you need help using Chaldea, assistance with your account, or wish to submit a suggestion, privacy complaint or personal information rights request.</p><h2 id="email" tabindex="-1">Email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Email&quot;">​</a></h2><p>Email: <a href="mailto:support@chaldea.center" target="_blank" rel="noreferrer">support@chaldea.center</a></p><p>Use email for account assistance, privacy complaints and requests involving personal information. Do not post passwords, Tokens, verification codes or other sensitive information in public issues or communities.</p><h2 id="privacy-contact" tabindex="-1">Privacy questions and rights requests <a class="header-anchor" href="#privacy-contact" aria-label="Permalink to &quot;Privacy questions and rights requests {#privacy-contact}&quot;">​</a></h2><p>To request access, a copy, correction, completion or deletion of personal information, withdraw consent, close an account or object to processing, contact us by <a href="mailto:support@chaldea.center" target="_blank" rel="noreferrer">email</a>. See the <a href="./privacy">Privacy Policy</a> for the relevant processing rules.</p><p>To help us handle your request, please describe:</p><ul><li>The type of request and the specific assistance you need.</li><li>If the request concerns an account, information needed to locate it, such as your username. We will seek further identity verification only as necessary to verify the request.</li></ul><p>Privacy requests do not require logs, screenshots or complete user data by default. Do not send passwords, Tokens or verification codes.</p><p>We will <strong>respond within 15 working days</strong> after receiving a privacy complaint or rights request. If we cannot fulfill a request directly, we will explain the reason and available next steps. This response period applies to privacy matters.</p><h2 id="issues-and-suggestions" tabindex="-1">Issues and suggestions <a class="header-anchor" href="#issues-and-suggestions" aria-label="Permalink to &quot;Issues and suggestions&quot;">​</a></h2><ul><li><strong>In-app feedback</strong>: Use Settings → Feedback for technical issues or suggestions. In-app feedback includes diagnostic logs and a user data file; use email for privacy rights requests.</li><li><strong>GitHub Issues</strong>: Report issues or feature requests suitable for public discussion in the <a href="https://github.com/chaldea-center/chaldea/issues" target="_blank" rel="noreferrer">Chaldea issue tracker</a>. Search existing issues before submitting a new one.</li></ul><p>GitHub Issues is public. Remove account details and other sensitive information before posting screenshots or logs. You do not need to leave your personal email address in a public issue.</p><h2 id="community" tabindex="-1">Community <a class="header-anchor" href="#community" aria-label="Permalink to &quot;Community&quot;">​</a></h2><ul><li><a href="https://discord.gg/5M6w5faqjP" target="_blank" rel="noreferrer">Discord community</a></li><li><a href="https://bbs.nga.cn/read.php?tid=24926789" target="_blank" rel="noreferrer">NGA FGO community thread</a></li></ul><p>Use these communities for general discussion and sharing experiences. Send account details, privacy complaints and personal information rights requests by email.</p><h2 id="preparing-feedback" tabindex="-1">Preparing feedback <a class="header-anchor" href="#preparing-feedback" aria-label="Permalink to &quot;Preparing feedback&quot;">​</a></h2><p>When reporting a technical issue, include the following where possible:</p><ul><li>App and data versions, device model and operating system version.</li><li>The affected page, steps to reproduce, expected behavior and actual behavior.</li><li>Relevant screenshots or logs with sensitive information removed, if available.</li></ul><p>For feature suggestions, describe your use case, the difficulty you face and the behavior you would like. If you would like a reply to email or in-app feedback, provide a working contact method.</p>',21)])])}const f=a(o,[["render",r]]);export{h as __pageData,f as default};
